import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.BywSET8q.js";const f=JSON.parse('{"title":"Project Structure","description":"","frontmatter":{},"headers":[],"relativePath":"docs/structure.md","filePath":"docs/structure.md"}'),i={name:"docs/structure.md"};function n(l,a,s,c,h,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h1><p>The Okta Client JavaScript ecosystem consists of multiple libraries, each focusing on a specific area or API. There are four tiers of libraries:</p><h4 id="platform-agnostic" tabindex="-1">Platform Agnostic <a class="header-anchor" href="#platform-agnostic" aria-label="Permalink to &quot;Platform Agnostic&quot;">​</a></h4><ol><li><a href="#tier-1"><strong>Foundational</strong></a>: Foundational libraries upon which other libraries are built.</li><li><a href="#tier-2"><strong>Token Acquisition &amp; API Clients</strong></a>: Libraries for interacting with spec-compliant OAuth2 Authorization Servers and other Okta REST APIs.</li></ol><h4 id="platform-specific" tabindex="-1">Platform Specific <a class="header-anchor" href="#platform-specific" aria-label="Permalink to &quot;Platform Specific&quot;">​</a></h4><ol start="3"><li><a href="#tier-3"><strong>Platform</strong></a>: Libraries that build upon and extend tier 1 and 2 libraries, targeting specific platforms like browsers or Node.js.</li><li><a href="#tier-4"><strong>Framework</strong></a>: Libraries built for specific frameworks (such as React, Angular, or Express) to facilitate integration with the Okta Client ecosystem.</li></ol><h2 id="tier-1" tabindex="-1">Tier 1: Foundation Libraries <a class="header-anchor" href="#tier-1" aria-label="Permalink to &quot;Tier 1: Foundation Libraries {#tier-1}&quot;">​</a></h2><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/auth-foundation/"><code>@okta/auth-foundation</code></a> – Defines foundational classes and interfaces. All other libraries within the project will have a dependency on <code>auth-foundation</code>.</li></ul><h2 id="tier-2" tabindex="-1">Tier 2: Token Acquisition Libraries &amp; API Clients <a class="header-anchor" href="#tier-2" aria-label="Permalink to &quot;Tier 2: Token Acquisition Libraries &amp; API Clients {#tier-2}&quot;">​</a></h2><h4 id="token-acquisition" tabindex="-1">Token Acquisition <a class="header-anchor" href="#token-acquisition" aria-label="Permalink to &quot;Token Acquisition&quot;">​</a></h4><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/oauth2-flows/"><code>@okta/oauth2-flows</code></a> – Implementations of OAuth2 authentication flows, such as Authorization Code Flow.</li></ul><h4 id="api-clients-–-coming-soon" tabindex="-1">API Clients – Coming Soon <a class="header-anchor" href="#api-clients-–-coming-soon" aria-label="Permalink to &quot;API Clients – Coming Soon&quot;">​</a></h4><ul><li><code>@okta/myaccount-client</code> – (TBT) <code>APIClient</code> for the <a href="https://developer.okta.com/docs/reference/api/myaccount/" target="_blank" rel="noreferrer">Okta MyAccount</a> API</li></ul><h2 id="tier-3" tabindex="-1">Tier 3: Platform Libraries <a class="header-anchor" href="#tier-3" aria-label="Permalink to &quot;Tier 3: Platform Libraries {#tier-3}&quot;">​</a></h2><h4 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h4><ul><li><a href="https:/okta.github.io/okta-client-javascript/api/spa-platform/"><code>@okta/spa-platform</code></a> – Platform implementations and extensions for browser environments.</li><li><a href="https:/okta.github.io/okta-client-javascript/api/react-native-platform/"><code>@okta/react-native-platform</code></a> – Platform implementations and extensions for React Native environments.</li><li><code>@okta/nodejs-platform</code> - COMING SOON</li></ul><h2 id="tier-4" tabindex="-1">Tier 4: Framework Libraries <a class="header-anchor" href="#tier-4" aria-label="Permalink to &quot;Tier 4: Framework Libraries {#tier-4}&quot;">​</a></h2><h4 id="browser-–-coming-soon" tabindex="-1">Browser – Coming Soon <a class="header-anchor" href="#browser-–-coming-soon" aria-label="Permalink to &quot;Browser – Coming Soon&quot;">​</a></h4><ul><li><a href="https://github.com/okta/okta-react" target="_blank" rel="noreferrer"><code>@okta/okta-react</code></a> (New Integration)</li><li><a href="https://github.com/okta/okta-angular" target="_blank" rel="noreferrer"><code>@okta/okta-angular</code></a> (New Integration)</li><li><a href="https://github.com/okta/okta-vue" target="_blank" rel="noreferrer"><code>@okta/okta-vue</code></a> (New Integration)</li></ul>',19)])])}const m=e(i,[["render",n]]);export{f as __pageData,m as default};
